#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by unity-vfx-maker. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/FireballLoop/Plan.md
    public static class FireballLoopBuild
    {
        const string Effect = "FireballLoop";
        const string Root = "Assets/VFX/" + Effect;

        static readonly Color Violet = Hex(0x4A1030), Red = Hex(0xC8281E), Orange = Hex(0xFF7A1F),
                              Yellow = Hex(0xFFC93C), CoreLight = Hex(0xFFF1B0), CoreDark = Hex(0x3A1226);

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");

            // 1. Textures
            var glow = ImportTexture(Root + "/Textures/T_Glow_Soft.png", 256);
            var flip = ImportTexture(Root + "/Textures/T_Fire_Flipbook_4x4.png", 512, alphaFromGray: true);
            var blob = ImportTexture(Root + "/Textures/T_Fire_Blob_2x2.png", 512, alphaFromGray: true);
            var tongue = ImportTexture(Root + "/Textures/T_Fire_Tongue_2x2.png", 512);
            var ember = ImportTexture(Root + "/Textures/T_Ember_Chunk.png", 256);

            // 2. Materials
            var mGlow = Material(Root + "/Materials/M_" + Effect + "_Glow_Add.mat", VfxBlend.Additive, glow);
            var mFlameAlpha = Material(Root + "/Materials/M_" + Effect + "_Flame_Alpha.mat", VfxBlend.Alpha, flip);
            var mBlobAlpha = Material(Root + "/Materials/M_" + Effect + "_Hollow_Alpha.mat", VfxBlend.Alpha, blob);
            var mTongue = Material(Root + "/Materials/M_" + Effect + "_Tongue_Add.mat", VfxBlend.Additive, tongue);
            var mEmber = Material(Root + "/Materials/M_" + Effect + "_Ember_Add.mat", VfxBlend.Additive, ember);

            // 3. Layers (ball centre at origin, flames rise along +Y)
            var root = new GameObject("VFX_" + Effect);
            var t = root.transform;

            Aura(t, mGlow);
            Body(t, "Body_Outer", mFlameAlpha, Violet, Red, 1.3f, 1.6f, rate: 13, shellRadius: 0.34f, order: 0);
            Body(t, "Body_Mid", mFlameAlpha, Orange, Red, 1.0f, 1.25f, rate: 13, shellRadius: 0.24f, order: 1);
            Hollow(t, mBlobAlpha);
            CoreLight_(t, mGlow, mEmber);
            Tongues(t, mTongue);
            Embers(t, mEmber);

            // 4. Save, validate, preview (3/4 top-down), demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            Finish(prefab, Root, Effect, new[] { 0.4f, 0.9f, 1.4f, 2.0f, 2.7f },
                   cameraPos: new Vector3(2.2f, 2.2f, -3.0f), lookAt: new Vector3(0f, 0.6f, 0f));
        }

        public static void BuildBatch() => RunBatch(Build);

        static ParticleSystem Looping(Transform parent, string name, Material mat, float life, float rate, int max, int order)
        {
            var ps = Particle(parent, name, mat, lifetime: life);
            var main = ps.main;
            main.loop = true;
            main.duration = 1f;
            main.prewarm = true;
            main.maxParticles = max;
            var em = ps.emission;
            em.rateOverTime = rate;
            em.SetBursts(new ParticleSystem.Burst[0]);
            ps.GetComponent<ParticleSystemRenderer>().sortingOrder = order;
            return ps;
        }

        static void Flipbook(ParticleSystem ps, int x, int y, bool animate, float lastFrame = 0.93f)
        {
            var tsa = ps.textureSheetAnimation;
            tsa.enabled = true;
            tsa.numTilesX = x; tsa.numTilesY = y;
            tsa.frameOverTime = animate ? Curve(0f, 0f, 1f, lastFrame) : new ParticleSystem.MinMaxCurve(0f, 0.999f);
        }

        static void Aura(Transform parent, Material mat)
        {
            var ps = Looping(parent, "Aura_Glow", mat, life: 2.4f, rate: 1f, max: 4, order: -2);
            var main = ps.main;
            main.startSize = 3.2f;
            var c = Hex(0x7A1E3C);
            main.startColor = new Color(c.r, c.g, c.b, 0.55f);
            SizeOverLifetime(ps, 0f, 0.85f, 0.5f, 1.05f, 1f, 0.9f);
            AlphaOverLifetime(ps, 0f, 0f, 0.4f, 1f, 1f, 0f);
        }

        // Upright flame flipbook scattered on a shell around the ball: one tinted band of the body.
        static void Body(Transform parent, string name, Material mat, Color from, Color to, float sizeMin, float sizeMax,
                         float rate, float shellRadius, int order)
        {
            var ps = Looping(parent, name, mat, life: 0.8f, rate: rate, max: 14, order: order);
            var main = ps.main;
            main.startSize = new ParticleSystem.MinMaxCurve(sizeMin, sizeMax);
            main.startSpeed = 0f;
            main.startRotation = new ParticleSystem.MinMaxCurve(-0.35f, 0.35f);

            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = shellRadius;
            shape.radiusThickness = 0.15f;
            shape.position = new Vector3(0f, -0.1f, 0f);

            var vel = ps.velocityOverLifetime;
            vel.enabled = true;
            vel.space = ParticleSystemSimulationSpace.Local;
            vel.x = 0f; vel.y = 0.5f; vel.z = 0f;

            SizeOverLifetime(ps, 0f, 0.75f, 0.35f, 1f, 1f, 0.8f);
            ColorOverLifetime(ps, new[] { from, to }, 0f, 0f, 0.15f, 1f, 0.75f, 1f, 1f, 0f);
            Flipbook(ps, 4, 4, animate: true);
        }

        // Dark swirling cavity in the middle of the ball.
        static void Hollow(Transform parent, Material mat)
        {
            var ps = Looping(parent, "Core_Hollow", mat, life: 3f, rate: 1f, max: 4, order: 2);
            var main = ps.main;
            main.startSize = new ParticleSystem.MinMaxCurve(0.42f, 0.52f);
            main.startColor = CoreDark;
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            main.startSpeed = 0f;
            var rot = ps.rotationOverLifetime;
            rot.enabled = true;
            rot.z = new ParticleSystem.MinMaxCurve(-1f, 1f);
            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.04f;
            shape.position = new Vector3(0f, -0.1f, 0f);
            AlphaOverLifetime(ps, 0f, 0f, 0.2f, 0.85f, 0.8f, 0.85f, 1f, 0f);
            Flipbook(ps, 2, 2, animate: false);
        }

        static void CoreLight_(Transform parent, Material glowMat, Material emberMat)
        {
            var g = Looping(parent, "Core_Light", glowMat, life: 1.2f, rate: 1f, max: 3, order: 3);
            var gm = g.main;
            gm.startSize = 0.38f;
            gm.startColor = new Color(Yellow.r, Yellow.g, Yellow.b, 0.6f);
            g.transform.localPosition = new Vector3(0f, -0.1f, 0f);
            SizeOverLifetime(g, 0f, 0.8f, 0.5f, 1.15f, 1f, 0.8f);
            AlphaOverLifetime(g, 0f, 0f, 0.4f, 1f, 1f, 0f);

            var s = Looping(parent, "Core_Spark", emberMat, life: 0.5f, rate: 5f, max: 4, order: 4);
            var sm = s.main;
            sm.startSize = new ParticleSystem.MinMaxCurve(0.12f, 0.22f);
            sm.startColor = CoreLight;
            sm.startSpeed = 0f;
            sm.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            var shape = s.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.15f;
            shape.position = new Vector3(0f, -0.1f, 0f);
            AlphaOverLifetime(s, 0f, 0f, 0.3f, 1f, 1f, 0f);
        }

        // Few big tongues rising from the top of the ball, thinning towards the tip.
        static void Tongues(Transform parent, Material mat)
        {
            var ps = Looping(parent, "Tongues", mat, life: 1f, rate: 4f, max: 6, order: 5);
            var main = ps.main;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.9f, 1.2f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.9f, 1.4f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.9f, 1.3f);
            main.startRotation = new ParticleSystem.MinMaxCurve(-0.25f, 0.25f);

            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Cone;
            shape.angle = 10f;
            shape.radius = 0.22f;
            shape.rotation = new Vector3(-90f, 0f, 0f);  // cone axis -> +Y
            shape.position = new Vector3(0f, 0.25f, 0f);

            SizeOverLifetime(ps, 0f, 0.6f, 0.35f, 1f, 1f, 0.25f);
            ColorOverLifetime(ps, new[] { Yellow, Orange, Red }, 0f, 0f, 0.1f, 1f, 0.6f, 0.8f, 1f, 0f);
            Flipbook(ps, 2, 2, animate: false);
        }

        static void Embers(Transform parent, Material mat)
        {
            var ps = Looping(parent, "Embers", mat, life: 2.5f, rate: 3f, max: 12, order: 6);
            var main = ps.main;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.startLifetime = new ParticleSystem.MinMaxCurve(2f, 3f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 0.5f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.07f, 0.14f);
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, Mathf.PI * 2f);
            main.gravityModifier = -0.05f;

            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.45f;

            var noise = ps.noise;
            noise.enabled = true;
            noise.strength = 0.35f;
            noise.quality = ParticleSystemNoiseQuality.Low;

            ColorOverLifetime(ps, new[] { Yellow, Orange, Red }, 0f, 0f, 0.1f, 1f, 0.6f, 0.9f, 1f, 0f);
        }

        static Color Hex(int rgb) => new Color(((rgb >> 16) & 0xFF) / 255f, ((rgb >> 8) & 0xFF) / 255f, (rgb & 0xFF) / 255f, 1f);
    }
}
#endif
